picking = env['stock.picking'].browse(record.res_id).exists()

if picking and picking.state == 'assigned':
    if picking.filtered_domain(
        env.ref(
            'fmcg_business_automation.ir_filter_stock_picking_missing_lot_serial'
        )._get_eval_domain()
    ):
        env.ref(
            'fmcg_business_automation.action_notify_picking_missing_lot_serial'
        ).with_context(
            active_model='mail.activity',
            active_id=record.id,
            active_ids=[record.id],
        ).run()
    else:
        picking.button_validate()
